int rows[2], cols[2];
int r = 0, c = 0;
for (int i = 0; i < 3; ++i) {
    if (i != row) rows[r++] = i;
    if (i != col) cols[c++] = i;
}
double minor = m(rows[0], cols[0]) * m(rows[1], cols[1]) -
               m(rows[0], cols[1]) * m(rows[1], cols[0]);
double sign = ((row + col) % 2 == 0) ? 1.0 : -1.0;
return sign * minor;
